const IK_RIG_REST_REF = { rHand: [-0.11599858850240707, 0.9928736090660095, -0.00641510309651494, 0.026555685326457024], rThumb1: [0.04745800793170929, 0.7883297801017761, 0.4728289842605591, 0.3907897472381592] }
