  const tipTwistT = val(FINGER_TIP_TWIST_KEY[fingerName]) / 100
  const baseOnlyCurlT = val(FINGER_BASE_ONLY_CURL_KEY[fingerName]) / 100
  const tipOnlyCurlT = val(FINGER_TIP_ONLY_CURL_KEY[fingerName]) / 100
