    if (i === 0) bone.rotateZ(rad(sign * maxDegs[0] * baseOnlyCurlT))
    if (i === 1) bone.rotateZ(rad(sign * maxDegs[1] * midOnlyCurlT))
    if (i === joints.length - 1) bone.rotateZ(rad(sign * maxDegs[i] * tipOnlyCurlT))
