  FINGER_NAMES.forEach((name) => { boneQuatsViaTransition[name] = hand.skinnedMesh.skeleton.getBoneByName(FINGER_JOINTS[name][0]).quaternion.clone() })

  POSE_PRESET_KEYS.forEach((key) => { cfg[key] = savedCfgSnapshot[key] })
